update_md5_f3d1741396f54f756def33ca5808f.find_text:
export async function readWasmAsset(relativePath: string): Promise<LoadedWasmAsset> {
  const tried = wasmAssetCandidates(relativePath)
  for (const candidate of tried) {
    const file = Bun.file(candidate)
    if (!(await file.exists())) continue
    return { bytes: await file.arrayBuffer(), path: candidate, tried }
  }
  return { bytes: null, path: null, tried }
}

update_md5_f3d1741396f54f756def33ca5808f.content_md5_f3d1741396f54f756def33ca5808:
export async function resolveWasmAssetPath(relativePath: string): Promise<string | undefined> {
  for (const candidate of wasmAssetCandidates(relativePath)) {
    if (await Bun.file(candidate).exists()) return candidate
  }
  return undefined
}

export async function readWasmAsset(relativePath: string): Promise<LoadedWasmAsset> {
  const tried = wasmAssetCandidates(relativePath)
  for (const candidate of tried) {
    const file = Bun.file(candidate)
    if (!(await file.exists())) continue
    return { bytes: await file.arrayBuffer(), path: candidate, tried }
  }
  return { bytes: null, path: null, tried }
}

update_md5_d36b143b29c7a0c8200f1b80865f4.find_text:
const treePath = resolveWasm(treeWasm)
// web-tree-sitter types require full EmscriptenModule, but runtime only needs locateFile
await (Parser.init as any)({
  locateFile() {
    return treePath
  },
})
const { default: bashWasm } = await import("tree-sitter-bash/tree-sitter-bash.wasm" as string, {
  with: { type: "wasm" },
})
const { default: psWasm } = await import("tree-sitter-powershell/tree-sitter-powershell.wasm" as string, {
  with: { type: "wasm" },
})
const bashPath = resolveWasm(bashWasm)
const psPath = resolveWasm(psWasm)
const [bashLanguage, psLanguage] = await Promise.all([Language.load(bashPath), Language.load(psPath)])

